/**
 * Regenerates lib/domain/ruleRegistryData.ts from legislative-reference/fraud_claim_rule_registry.csv.
 * Run after editing the CSV: npm run build:rules
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { rulesFromCsv } from "../lib/domain/ruleRegistry";

const root = join(__dirname, "..");
const rules = rulesFromCsv(readFileSync(join(root, "legislative-reference", "fraud_claim_rule_registry.csv"), "utf8"));
const out = `/**
 * GENERATED by \`npm run build:rules\` from legislative-reference/fraud_claim_rule_registry.csv.
 * Do not edit by hand; edit the CSV and regenerate. See ruleRegistry.ts.
 */
import type { RegistryRule } from "./ruleRegistry";

export const RULE_REGISTRY: RegistryRule[] = ${JSON.stringify(rules, null, 2)};
`;
writeFileSync(join(root, "lib", "domain", "ruleRegistryData.ts"), out);
console.log(`Wrote ${rules.length} rules to lib/domain/ruleRegistryData.ts`);
